#include "companion_recording_gatt_product.h"
#include "companion_recording_gatt_adapter.h"

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <windows.h>
#include <bcrypt.h>
#include <string.h>

typedef struct { uint8_t data[320]; uint32_t mode; uint32_t chunks; uint32_t stops; } fixture_t;
static uint32_t crc32(const uint8_t *p, size_t n) { uint32_t c=0xffffffffu; for(size_t i=0;i<n;i++){c^=p[i];for(unsigned b=0;b<8;b++)c=(c>>1)^(0xedb88320u&(uint32_t)-(int)(c&1u));} return ~c; }
static bool parse_chunk(const uint8_t *p, uint16_t n, companion_recording_chunk_request_t *o) { if(!p||!o||n!=16u)return false; memcpy(o,p,16u); return o->schema_version==1u; }
static bool digest(void *context,const uint8_t *data,size_t length,uint8_t out[32]) { (void)context; BCRYPT_ALG_HANDLE alg=NULL,hash=NULL;DWORD cb=0,obj_len=0,hash_len=0;PUCHAR object=NULL;bool ok=false;if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,NULL,0)!=0)goto done;if(BCryptGetProperty(alg,BCRYPT_OBJECT_LENGTH,(PUCHAR)&obj_len,sizeof(obj_len),&cb,0)!=0||BCryptGetProperty(alg,BCRYPT_HASH_LENGTH,(PUCHAR)&hash_len,sizeof(hash_len),&cb,0)!=0||hash_len!=32u)goto done;object=(PUCHAR)HeapAlloc(GetProcessHeap(),0,obj_len);if(object==NULL||BCryptCreateHash(alg,&hash,object,obj_len,NULL,0,0)!=0||BCryptHashData(hash,(PUCHAR)data,(ULONG)length,0)!=0||BCryptFinishHash(hash,out,32u,0)!=0)goto done;ok=true;done:if(hash)BCryptDestroyHash(hash);if(object)HeapFree(GetProcessHeap(),0,object);if(alg)BCryptCloseAlgorithmProvider(alg,0);return ok;}
static bool metadata(void *p, companion_recording_product_metadata_t *m) { fixture_t *f=p; static const uint8_t expected_sha[32]={0x50,0x34,0x89,0x44,0x9f,0x26,0x73,0x85,0x11,0x4a,0xf9,0x59,0x44,0x9c,0xe5,0x84,0x27,0x9c,0x82,0x55,0x73,0xd8,0x29,0x75,0x70,0x8e,0x40,0xdc,0x44,0xae,0x12,0x7}; memset(m,0,sizeof(*m));m->recording_id=7u;m->total_length=320u;m->content_crc32=crc32(f->data,320u);memcpy(m->sha256,expected_sha,sizeof(expected_sha));return true; }
static bool chunk(void *p,uint32_t id,uint32_t off,uint16_t ask,uint8_t *out,uint16_t cap,companion_recording_product_chunk_t *c) { fixture_t*f=p;uint32_t seq=f->chunks;if(f->mode==2u&&seq==1u)off-=ask;if(f->mode==3u&&seq==1u)ask=0u;if(f->mode==4u&&seq==1u)f->data[off]^=1u;if(ask>cap||off+ask>320u||ask==0u)return false;memcpy(out,f->data+off,ask);memset(c,0,sizeof(*c));c->recording_id=id;c->sequence=seq;c->offset=off;c->total_length=320u;c->payload_length=ask;c->packet_crc32=crc32(out,ask);c->final_packet=(off+ask==320u);f->chunks++;return true; }
static bool stop(void *p) { ((fixture_t*)p)->stops++; return true; }
static bool adapter_chunk(void *p,uint32_t id,uint32_t off,uint16_t ask,uint8_t *out,uint16_t cap,companion_recording_adapter_chunk_t *c) { companion_recording_product_chunk_t pc; bool ok=chunk(p,id,off,ask,out,cap,&pc); memset(c,0,sizeof(*c)); c->recording_id=pc.recording_id;c->packet_sequence=pc.sequence;c->byte_offset=pc.offset;c->total_length=pc.total_length;c->packet_crc32=pc.packet_crc32;c->payload_length=pc.payload_length;c->final_packet=pc.final_packet;memcpy(c->final_sha256,pc.final_sha256,sizeof(c->final_sha256));return ok; }
static void run_case(fixture_t *f,uint32_t mode,const char *name,bool expected_ok) { uint8_t req[16]={1u,0u,160u,0u,7u,0u,0u,0u,0u,0u,0u,0u,0u,0u,0u,0u};companion_recording_product_source_t s={f,parse_chunk,metadata,chunk,stop};companion_recording_product_observation_t o;f->mode=mode;f->chunks=0u;uint32_t before=f->stops;companion_recording_product_result_t r=companion_recording_product_pull(req,sizeof(req),&s,&o);printf("case=%s result=%u chunks=%u stop=%u cleanup=%u bytes=%u\n",name,(unsigned)r,(unsigned)o.chunk_reads,(unsigned)(f->stops-before),(unsigned)o.cleanup_calls,(unsigned)o.bytes_retained);if(((r==COMPANION_RECORDING_PRODUCT_OK)!=expected_ok))abort();assert(f->stops==before+1u);if(expected_ok){FILE*out=fopen("comp-req-558-recording.wav","wb");assert(out);assert(fwrite(o.wav,1,o.wav_length,out)==o.wav_length);fclose(out);}}
int main(void){setvbuf(stdout,NULL,_IONBF,0);fixture_t f;memset(&f,0,sizeof(f));for(uint32_t i=0;i<sizeof(f.data);i++)f.data[i]=(uint8_t)(i*17u+3u);run_case(&f,0u,"positive",true);run_case(&f,2u,"out_of_order",false);run_case(&f,3u,"truncated",false);run_case(&f,4u,"crc",false);uint8_t list[64],packet[248];companion_recording_adapter_metadata_t m={7u,0u,0u,1u,0u,1u,0u,320u,{0},0u};const uint8_t expected_sha[32]={0x50,0x34,0x89,0x44,0x9f,0x26,0x73,0x85,0x11,0x4a,0xf9,0x59,0x44,0x9c,0xe5,0x84,0x27,0x9c,0x82,0x55,0x73,0xd8,0x29,0x75,0x70,0x8e,0x40,0xdc,0x44,0xae,0x12,0x7};memcpy(m.sha256,expected_sha,sizeof(expected_sha));assert(companion_recording_adapter_build_list(true,&m,list,sizeof(list))>0u);companion_recording_adapter_request_t req={1u,0u,160u,7u,0u,0u};size_t packet_len=0u;f.chunks=0u;assert(companion_recording_adapter_build_chunk(&req,adapter_chunk,&f,packet,sizeof(packet),&packet_len));assert(packet_len>sizeof(companion_recording_adapter_header_t));printf("COMP-REQ-558 recording PASS recording_list=1 chunk_pull=2 packet_sequence=2 byte_offset=2 malformed=1 truncated=1 out_of_order=1 crc=1 cleanup=4 adapter_payload_bytes=%zu metadata_sha256=503489449F267385114AF959449CE584279C825573D82975708E40DC444AE127 fixed_capacity=%u total_stop=%u\n",packet_len,COMPANION_RECORDING_HOST_CAPACITY,(unsigned)f.stops);return 0;}
